const items = $input.all();
const creds = $('Merge Triggers').item.json;

let invoicesProcessando = [];
let invoicesAguardando  = [];
let configs  = [];
let clients  = [];

for (const item of items) {
  const j = item?.json;
  if (!j) continue;
  if (Array.isArray(j.invoices_processando)) invoicesProcessando = j.invoices_processando;
  if (Array.isArray(j.invoices_aguardando))  invoicesAguardando  = j.invoices_aguardando;
  if (Array.isArray(j.configs))  configs  = j.configs;
  if (Array.isArray(j.clients))  clients  = j.clients;
}

// Junta processando + aguardando e filtra os que têm mais de 10 min sem atualização
const cutoff = new Date(Date.now() - 10 * 60 * 1000).toISOString();
const allInvoices = invoicesProcessando.concat(invoicesAguardando)
  .filter(function(inv) { return inv.updated_at < cutoff; });

if (allInvoices.length === 0) {
  return [{ json: { checked: 0, message: 'Nenhuma nota em processamento para verificar' } }];
}

// Mapas para lookup rápido
const configMap = {};
configs.forEach(function(c) {
  if (c.organization_id && c.config) configMap[c.organization_id] = c.config;
});

const clientMap = {};
clients.forEach(function(c) { clientMap[c.id] = c; });

const results    = [];
const patches    = []; // { id, patch } para atualizar no Supabase
const byOrg      = {};

for (const invoice of allInvoices) {
  const orgId = invoice.organization_id;
  const config = configMap[orgId] || {};

  if (!byOrg[orgId]) byOrg[orgId] = { checked: 0, autorizada: 0, rejeitada: 0, skip: 0 };
  byOrg[orgId].checked++;

  if (!config.api_key) {
    results.push({ id: invoice.id, result: 'skip', reason: 'no_api_key' });
    byOrg[orgId].skip++;
    continue;
  }

  const baseUrl = config.sandbox_mode === true
    ? 'https://sandbox.notaas.com.br'
    : 'https://platform.notaas.com.br';

  if (invoice.notaas_id) {
    // Tem notaas_id — agenda consulta à Notaas
    results.push({
      id:        invoice.id,
      org_id:    orgId,
      action:    'check',
      notaas_id: invoice.notaas_id,
      api_key:   config.api_key,
      base_url:  baseUrl
    });
  } else {
    // Sem notaas_id — agenda reemissão
    const client = clientMap[invoice.client_id];
    if (!client) {
      results.push({ id: invoice.id, result: 'skip', reason: 'client_not_found' });
      byOrg[orgId].skip++;
      continue;
    }

    const codigoServico = (invoice.codigo_servico || config.codigo_servico_padrao || '').replace(/\D/g, '');
    if (!codigoServico) {
      patches.push({ id: invoice.id, patch: { status: 'rejeitada', erro_mensagem: 'Código de serviço não configurado' } });
      results.push({ id: invoice.id, result: 'rejeitada', reason: 'no_codigo_servico' });
      byOrg[orgId].rejeitada++;
      continue;
    }

    const docDigits = (client.document || '').replace(/\D/g, '');
    const tomador = {};
    if (docDigits.length === 11) tomador.cpf  = docDigits;
    else                         tomador.cnpj = docDigits;
    tomador.nome  = client.company || client.name;
    tomador.email = client.email || null;
    tomador.endereco = {
      logradouro:  client.address_street       || '',
      numero:      client.address_number       || '',
      complemento: client.address_complement   || '',
      bairro:      client.address_neighborhood || '',
      cidade:      client.address_city         || '',
      uf:          client.address_state        || '',
      cep:         client.address_zip          || ''
    };

    results.push({
      id:       invoice.id,
      org_id:   orgId,
      action:   'emit',
      api_key:  config.api_key,
      base_url: baseUrl,
      notaas_payload: {
        tomador,
        servico:    { codigo: codigoServico, descricao: invoice.descricao_servico || config.descricao_servico_padrao || 'Prestação de serviços' },
        valores:    { total: invoice.valor_servico, aliquotaIss: invoice.aliquota_iss != null ? invoice.aliquota_iss : (config.aliquota_iss_padrao || 5) },
        competencia: invoice.competencia
      }
    });
  }
}

return [{ json: {
  results,
  patches,
  byOrg,
  supabase_url:     creds.supabase_url,
  supabase_api_key: creds.supabase_api_key,
  total:            allInvoices.length
}}];

// Executa as consultas/emissões na Notaas e coleta os patches para o Supabase
const d = $input.first().json;
const sbUrl = d.supabase_url;
const sbKey = d.supabase_api_key;
const sbH   = { 'apikey': sbKey, 'Authorization': 'Bearer ' + sbKey, 'Content-Type': 'application/json' };

const finalPatches = [...(d.patches || [])];
const finalResults = [];
const byOrg = JSON.parse(JSON.stringify(d.byOrg || {}));

for (const item of (d.results || [])) {
  if (!item.action) {
    finalResults.push(item);
    continue;
  }

  if (!byOrg[item.org_id]) byOrg[item.org_id] = { checked: 0, autorizada: 0, rejeitada: 0, skip: 0 };

  if (item.action === 'check') {
    try {
      const res = await fetch(item.base_url + '/api/v1/notas/' + item.notaas_id, {
        headers: { 'x-api-key': item.api_key, 'Content-Type': 'application/json' },
        signal: AbortSignal.timeout(15000)
      });

      if (res.ok) {
        const nota = await res.json();
        if (nota && (nota.id || nota.numero)) {
          finalPatches.push({ id: item.id, patch: {
            status: 'emitida',
            notaas_id: nota.id || item.notaas_id,
            notaas_protocol: nota.protocol || null,
            numero: nota.numero || null,
            pdf_url: nota.pdf_url || null,
            xml_url: nota.xml_url || null,
            emitida_em: nota.emitida_em || new Date().toISOString(),
            erro_mensagem: null
          }});
          finalResults.push({ id: item.id, result: 'autorizada', numero: nota.numero });
          byOrg[item.org_id].autorizada++;
        } else {
          finalResults.push({ id: item.id, result: 'skip', reason: 'still_processing' });
          byOrg[item.org_id].skip++;
        }
      } else if (res.status === 404) {
        finalPatches.push({ id: item.id, patch: { status: 'rejeitada', erro_mensagem: 'Nota não encontrada na Notaas' } });
        finalResults.push({ id: item.id, result: 'rejeitada', reason: 'not_found' });
        byOrg[item.org_id].rejeitada++;
      } else {
        const errBody = await res.json().catch(function() { return {}; });
        const errMsg = errBody.message || errBody.error || ('HTTP ' + res.status);
        finalPatches.push({ id: item.id, patch: { status: 'rejeitada', erro_mensagem: errMsg } });
        finalResults.push({ id: item.id, result: 'rejeitada', reason: errMsg });
        byOrg[item.org_id].rejeitada++;
      }
    } catch (e) {
      finalResults.push({ id: item.id, result: 'skip', reason: 'network_error: ' + e.message });
      byOrg[item.org_id].skip++;
    }

  } else if (item.action === 'emit') {
    try {
      const res = await fetch(item.base_url + '/api/v1/emitir', {
        method: 'POST',
        headers: { 'x-api-key': item.api_key, 'Content-Type': 'application/json', 'User-Agent': 'MaestrIA-n8n-check/1.0' },
        body: JSON.stringify(item.notaas_payload),
        signal: AbortSignal.timeout(30000)
      });
      const body = await res.json().catch(function() { return {}; });
      const externalId = body.id || body.notaas_id || body.nota_id || null;
      const numero = body.numero || body.number || null;

      if (res.ok && (externalId || numero)) {
        finalPatches.push({ id: item.id, patch: {
          status: 'emitida',
          notaas_id: externalId,
          notaas_protocol: body.protocol || null,
          numero,
          pdf_url: body.pdf_url || body.pdfUrl || null,
          xml_url: body.xml_url || body.xmlUrl || null,
          emitida_em: body.emitida_em || new Date().toISOString(),
          erro_mensagem: null
        }});
        finalResults.push({ id: item.id, result: 'autorizada', numero });
        byOrg[item.org_id].autorizada++;
      } else {
        const msg = body.message || body.error || body.msg || ('HTTP ' + res.status);
        finalPatches.push({ id: item.id, patch: { status: 'rejeitada', erro_mensagem: typeof msg === 'string' ? msg : JSON.stringify(msg) } });
        finalResults.push({ id: item.id, result: 'rejeitada', reason: msg });
        byOrg[item.org_id].rejeitada++;
      }
    } catch (e) {
      finalResults.push({ id: item.id, result: 'skip', reason: 'emit_error: ' + e.message });
      byOrg[item.org_id].skip++;
    }
  }
}

// Aplica os patches no Supabase
for (const p of finalPatches) {
  try {
    await fetch(sbUrl + '/rest/v1/invoices?id=eq.' + p.id, {
      method: 'PATCH',
      headers: Object.assign({}, sbH, { 'Prefer': 'return=minimal' }),
      body: JSON.stringify(p.patch)
    });
  } catch (e) { /* best-effort */ }
}

// Registra resultado da checagem por organização
for (const orgId of Object.keys(byOrg)) {
  try {
    await fetch(sbUrl + '/rest/v1/rpc/update_fiscal_check_status', {
      method: 'POST',
      headers: sbH,
      body: JSON.stringify({
        p_organization_id: orgId,
        p_status: 'success',
        p_results: Object.assign({ checked_at: new Date().toISOString() }, byOrg[orgId])
      })
    });
  } catch (e) { /* best-effort */ }
}

return [{ json: { checked: d.total, results: finalResults } }];
